  for (int i = 0; i != 64; i++)
    {
      p[i] = i;
      q[i] = (i + 32) % 64;
    }
  __builtin_memcpy (pd_src, p, 64);
  __builtin_memcpy (ps_src, p, 64);
  __builtin_memcpy (epi64_src, p, 64);
  __builtin_memcpy (epi32_src, p, 64);
